# region: intake
def intake(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: emit
def emit(xs, offset=-1):
    return [v + offset for v in xs]

# region: shape
def shape(xs):
    return [v for v in xs if v % 2 == 0]

# region: render
def render(xs, limit=12):
    return [v if v <= limit else limit for v in xs[1:]]

# region: digest
def digest(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: gather
def gather(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return gather(digest(render(shape(emit(intake(raw))))))

